const input = $input.first().json;
const body = input.body ?? input;

const author = body.author ?? {};

let books = [];

if (Array.isArray(body.books)) {
  books = body.books;
} else if (typeof body.books_json === "string") {
  try {
    const parsed = JSON.parse(body.books_json);
    books = Array.isArray(parsed) ? parsed : [parsed];
  } catch (error) {
    const message =
      error instanceof Error ? error.message : String(error);
    throw new Error("Invalid books_json: " + message);
  }
} else if (Array.isArray(body.books_json)) {
  books = body.books_json;
} else if (body.books_json && typeof body.books_json === "object") {
  books = [body.books_json];
} else if (body.books && typeof body.books === "object") {
  books = [body.books];
}

if (!author.name || !author.email) {
  throw new Error("Payload must include author.name and author.email");
}

if (books.length === 0) {
  throw new Error("Payload must include a non-empty books array");
}

const number = (value) => {
  const result = Number(value);
  return Number.isFinite(result) ? result : 0;
};

const money = (value) =>
  Math.round((value + Number.EPSILON) * 100) / 100;

const formatMoney = (value) =>
  "₹" +
  money(value).toLocaleString("en-IN", {
    maximumFractionDigits: 2,
  });

const earned = money(
  books.reduce((sum, book) => sum + number(book.total_royalty_earned), 0)
);

const paid = money(
  books.reduce((sum, book) => sum + number(book.royalty_paid), 0)
);

const pending = money(
  books.reduce((sum, book) => sum + number(book.royalty_pending), 0)
);

const copiesSold = books.reduce(
  (sum, book) => sum + number(book.total_copies_sold),
  0
);

const publishedBooks = books.filter((book) =>
  String(book.status ?? "").toLowerCase().includes("published")
);

const today = new Date();
const y = today.getUTCFullYear();
const ends = [Date.UTC(y,0,0), Date.UTC(y,3,0), Date.UTC(y,6,0), Date.UTC(y,9,0), Date.UTC(y,12,0)];
const due = ends.map(e => new Date(e + 45*86400000)).find(d => d >= today) ?? new Date(Date.UTC(y + 1, 0, 0) + 45*86400000);
const dueDate = due.toISOString().slice(0, 10);

const requestId = String(
  body.request_id || `${author.author_id || author.email}-${Date.now()}`
);

return [
  {
    json: {
      request_id: requestId,
      author: {
        author_id: author.author_id || "",
        name: author.name,
        email: author.email,
        city: author.city || "",
      },
      summary: {
        total_books: books.length,
        published_books: publishedBooks.length,
        books_in_production: books.length - publishedBooks.length,
        total_copies_sold: copiesSold,
        total_royalty_earned: earned,
        total_royalty_paid: paid,
        total_royalty_pending: pending,
        payout_status:
          pending === 0
            ? "Fully paid"
            : pending < 1000
              ? "Below minimum - rolls over"
              : "Pending payout",
        minimum_payout_threshold: 1000,
        eligible_for_payout: pending >= 1000,
        indicative_due_date_utc: dueDate,
      },
      display: {
        total_earned: formatMoney(earned),
        total_paid: formatMoney(paid),
        total_pending: formatMoney(pending),
        threshold: formatMoney(1000),
        payout_due_date_long: due.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" }),
      },
      books: books.map((book) => ({
        book_id: book.book_id || "",
        title: book.title || "Untitled",
        isbn: book.isbn || "",
        genre: book.genre || "",
        status: book.status || "",
        mrp: number(book.mrp),
        total_copies_sold: number(book.total_copies_sold),
        total_royalty_earned: money(number(book.total_royalty_earned)),
        royalty_paid: money(number(book.royalty_paid)),
        royalty_pending: money(number(book.royalty_pending)),
        earned_display: formatMoney(number(book.total_royalty_earned)),
        paid_display: formatMoney(number(book.royalty_paid)),
        pending_display: formatMoney(number(book.royalty_pending)),
        last_royalty_payout_date: book.last_royalty_payout_date || "",
      })),
      callback_url:
        body.callback_url ||
        "https://coderakhil786.bubbleapps.io/version-test/api/1.1/wf/royalty_summary_callback",
      bubble_log_id: body.bubble_log_id || "",
    },
  },
];

